    is_sensitive_name(attr.name)
    is_empty_value(attr.value)
    result := {
        "type": "sec_empty_pass",
        "element": attr,
        "path": parent.path,
        "description": "Empty password in configuration - Password-related fields should not be set to empty or null values. (CWE-258)"
    }
}

